SET NAMES utf8mb4;

CREATE TABLE actividades (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    codigo_segmento INT UNSIGNED NOT NULL,
    segmento VARCHAR(200) NOT NULL,
    codigo_familia INT UNSIGNED NOT NULL,
    familia VARCHAR(200) NOT NULL,
    codigo_clase INT UNSIGNED NOT NULL,
    clase VARCHAR(200) NOT NULL,
    codigo_producto INT UNSIGNED NOT NULL UNIQUE,
    producto VARCHAR(200) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE ofertas (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    consecutivo VARCHAR(40) UNIQUE,
    objeto VARCHAR(150) NOT NULL,
    descripcion VARCHAR(400) NOT NULL,
    moneda VARCHAR(3) NOT NULL,
    presupuesto DECIMAL(15,2) NOT NULL,
    actividad_id INT UNSIGNED NOT NULL,
    fecha_inicio DATE NOT NULL,
    hora_inicio TIME NOT NULL,
    fecha_cierre DATE NOT NULL,
    hora_cierre TIME NOT NULL,
    estado VARCHAR(20) NOT NULL DEFAULT 'Registrada',
    creado_en DATETIME NOT NULL,
    actualizado_en DATETIME NOT NULL,
    CONSTRAINT fk_ofertas_actividad FOREIGN KEY (actividad_id) REFERENCES actividades(id),
    CONSTRAINT chk_moneda CHECK (moneda IN ('COP','USD','EUR')),
    CONSTRAINT chk_presupuesto CHECK (presupuesto > 0),
    CONSTRAINT chk_cronograma CHECK (TIMESTAMP(fecha_inicio,hora_inicio) < TIMESTAMP(fecha_cierre,hora_cierre))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE ofertas_documentos (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    licitacion_id INT UNSIGNED NOT NULL,
    titulo VARCHAR(100) NOT NULL,
    descripcion VARCHAR(200) NOT NULL,
    archivo VARCHAR(80) NOT NULL UNIQUE,
    nombre_original VARCHAR(255) NOT NULL,
    mime VARCHAR(80) NOT NULL,
    tamano INT UNSIGNED NOT NULL,
    creado_en DATETIME NOT NULL,
    CONSTRAINT fk_documentos_oferta FOREIGN KEY (licitacion_id) REFERENCES ofertas(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Catálogo UNSPSC del enunciado.
SET NAMES utf8mb4;
